// ============================================================
// NODE: Normalize Email Data
// Cleans and extracts all fields from the raw Gmail payload
// into a consistent shape used by every downstream node.
// ============================================================

const item = $input.item.json;

const fromRaw = item.from || '';
let senderEmail = '';
let senderName = '';

const emailMatch = fromRaw.match(/<([^>]+)>/);
if (emailMatch) {
  senderEmail = emailMatch[1].trim().toLowerCase();
  senderName = fromRaw.split('<')[0].trim().replace(/"/g, '');
} else {
  senderEmail = fromRaw.trim().toLowerCase();
  senderName = fromRaw.split('@')[0].trim();
}

const firstName = senderName.split(' ')[0] || 'there';
const bodyText = item.text || item.snippet || '';
const bodyClean = bodyText.replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim().substring(0, 3000);
const fullTextLower = `${item.subject || ''} ${bodyClean}`.toLowerCase();
const isReply = (item.subject || '').toLowerCase().startsWith('re:');

return {
  json: {
    messageId:     item.id || '',
    threadId:      item.threadId || '',
    senderEmail,
    senderName,
    firstName,
    subject:       item.subject || '(No Subject)',
    body:          bodyClean,
    fullTextLower,
    receivedAt:    item.date || new Date().toISOString(),
    isReply,
    _raw:          item
  }
};

// ============================================================
// NODE: Safety Filter
// MUST run before AI and before any reply logic.
// Uses hardcoded keywords — intentionally NOT AI-based.
// Deterministic = zero chance of missing dangerous language.
// ============================================================

const text = $input.item.json.fullTextLower || '';

const legalPatterns        = ['complaint','complain','solicitor','legal action','legal proceedings','lawsuit','sue you','taking you to court','court action','ombudsman','data breach','gdpr breach','ico','negligence','malpractice','report you','trading standards'];
const safeguardingPatterns = ['safeguarding','safeguard','at risk','risk of harm','child at risk','abuse','neglect','exploitation','domestic violence','domestic abuse','threatened','threatening','violence','police','social services'];
const crisisPatterns       = ['suicid','self harm','self-harm','selfharm','overdose','want to die','end my life','end it all','hurt myself','hurting myself','crisis','emergency','urgent help','in danger','not safe'];

const matchedLegal         = legalPatterns.filter(p => text.includes(p));
const matchedSafeguarding  = safeguardingPatterns.filter(p => text.includes(p));
const matchedCrisis        = crisisPatterns.filter(p => text.includes(p));

const isFlagged = matchedLegal.length > 0 || matchedSafeguarding.length > 0 || matchedCrisis.length > 0;

let flagCategory = '';
let flagReason   = '';

if (matchedCrisis.length > 0) {
  flagCategory = 'CRISIS_RISK';
  flagReason   = `Crisis language detected: ${matchedCrisis.join(', ')}`;
} else if (matchedSafeguarding.length > 0) {
  flagCategory = 'SAFEGUARDING';
  flagReason   = `Safeguarding language detected: ${matchedSafeguarding.join(', ')}`;
} else if (matchedLegal.length > 0) {
  flagCategory = 'LEGAL_COMPLAINT';
  flagReason   = `Legal/complaint language detected: ${matchedLegal.join(', ')}`;
}

return {
  json: {
    ...$input.item.json,
    safety: { isFlagged, flagCategory, flagReason }
  }
};

// ============================================================
// NODE: Parse AI Response
// Bulletproof JSON parser — every possible failure mode
// is handled and defaults to manual_review.
// ============================================================

const upstream = $input.item.json;
let aiText = '';

try {
  aiText = upstream.text || upstream.message?.content || upstream.choices?.[0]?.message?.content || upstream.content?.[0]?.text || '';
} catch(e) { aiText = ''; }

let ai = {};
try {
  const cleaned = aiText.replace(/```json/gi,'').replace(/```/g,'').trim();
  ai = JSON.parse(cleaned);
  if (!ai.intent || !ai.category) throw new Error('Missing required fields');
} catch(e) {
  ai = {
    intent: 'manual_review', category: 'manual_review',
    confidence: 0, reasoning: `Parse failed: ${e.message}`,
    firstName: '', isChild: false, gpName: '', location: '',
    mentionsPrice: false, mentionsWaitingTime: false,
    appointmentType: '', preferredDate: ''
  };
}

// Confidence gate — low confidence = manual review
if (ai.confidence < 0.75 && ai.intent !== 'manual_review') {
  ai.originalIntent   = ai.intent;
  ai.originalCategory = ai.category;
  ai.intent    = 'manual_review';
  ai.category  = 'manual_review';
  ai.reasoning = `Low confidence (${ai.confidence}). Was: intent=${ai.originalIntent}, category=${ai.originalCategory}`;
}

const bestFirstName = (ai.firstName && ai.firstName.trim()) ? ai.firstName : upstream.firstName || 'there';

return {
  json: {
    ...upstream,
    firstName:          bestFirstName,
    intent:             ai.intent,
    category:           ai.category,
    confidence:         ai.confidence,
    ai,
    isChild:            ai.isChild || false,
    gpName:             ai.gpName || '',
    location:           ai.location || '',
    mentionsPrice:      ai.mentionsPrice || false,
    mentionsWaitingTime: ai.mentionsWaitingTime || false,
    appointmentType:    ai.appointmentType || 'ADHD Assessment',
    preferredDate:      ai.preferredDate || ''
  }
};

// ============================================================
// BOOKING BRANCH — STEP 1
// Prepare date range to search Google Calendar for open slots
// ============================================================

const d = $input.item.json;
const now = new Date();
const twoWeeksLater = new Date();
twoWeeksLater.setDate(now.getDate() + 14);

let searchFrom = now;
if (d.preferredDate) {
  const preferred = new Date(d.preferredDate);
  if (!isNaN(preferred) && preferred > now) searchFrom = preferred;
}

return {
  json: {
    ...d,
    calendarSearchFrom: searchFrom.toISOString(),
    calendarSearchTo:   twoWeeksLater.toISOString()
  }
};

// ============================================================
// BOOKING BRANCH — STEP 2
// Pick best 3 slots and build the proposal email
// ============================================================

const allItems = $input.all();
const bookingData = allItems[0]?.json || {};

const slots = allItems
  .filter(item => item.json.start?.dateTime)
  .map(item => ({
    id:    item.json.id,
    start: item.json.start.dateTime,
    end:   item.json.end?.dateTime || ''
  }))
  .slice(0, 3);

if (slots.length === 0) {
  return { json: { ...bookingData, noSlotsFound: true, availableSlots: [] } };
}

const fmt = (dt) => ({
  date: new Date(dt).toLocaleDateString('en-GB', { weekday:'long', year:'numeric', month:'long', day:'numeric', timeZone:'Europe/London' }),
  time: new Date(dt).toLocaleTimeString('en-GB', { hour:'2-digit', minute:'2-digit', timeZone:'Europe/London' })
});

const slotLines = slots.map((s, i) => {
  const start = fmt(s.start);
  const end   = fmt(s.end);
  return `Option ${i+1}: ${start.date} at ${start.time}–${end.time}`;
}).join('\n');

const firstName = bookingData.firstName || 'there';
const apptType  = bookingData.appointmentType || 'appointment';

const emailBody = `Dear ${firstName},\n\nThank you for getting in touch — we would be happy to arrange a ${apptType} for you.\n\nWe currently have the following appointments available:\n\n${slotLines}\n\nPlease reply with which option works best for you and we will confirm your booking straight away.\n\nKind regards,\nAdmin Team\nREPLACE_WITH_CLINIC_NAME\nREPLACE_WITH_PHONE_NUMBER`;

return {
  json: {
    ...bookingData,
    noSlotsFound:   false,
    availableSlots: slots,
    emailSubject:   `Re: ${bookingData.subject}`,
    emailBody,
    slot1Id:    slots[0]?.id    || '',
    slot1Start: slots[0]?.start || '',
    slot1End:   slots[0]?.end   || '',
    slot2Id:    slots[1]?.id    || '',
    slot2Start: slots[1]?.start || '',
    slot2End:   slots[1]?.end   || '',
    slot3Id:    slots[2]?.id    || '',
    slot3Start: slots[2]?.start || '',
    slot3End:   slots[2]?.end   || ''
  }
};

// ============================================================
// CONFIRMATION BRANCH
// Patient replied confirming a slot — detect which option
// ============================================================

const d = $input.item.json;
const bodyLower = (d.body || '').toLowerCase();

let chosenOption = 0;

if (bodyLower.includes('option 1') || bodyLower.includes('first option') || bodyLower.includes('1st')) {
  chosenOption = 1;
} else if (bodyLower.includes('option 2') || bodyLower.includes('second option') || bodyLower.includes('2nd')) {
  chosenOption = 2;
} else if (bodyLower.includes('option 3') || bodyLower.includes('third option') || bodyLower.includes('3rd')) {
  chosenOption = 3;
}

// General confirmation with no specific option → default to option 1
if (chosenOption === 0) {
  const confirmWords = ['yes','confirm','that works','sounds good','perfect','great','happy with','book me in','go ahead','that\'s fine','works for me'];
  if (confirmWords.some(w => bodyLower.includes(w))) chosenOption = 1;
}

return {
  json: {
    ...d,
    chosenOption,
    needsManualConfirmation: chosenOption === 0
  }
};

// ============================================================
// CONFIRMATION BRANCH — STEP 2
// Map chosen option to slot start/end times
// ============================================================

const d = $input.item.json;
const opt = d.chosenOption || 1;

const slotStart = d[`slot${opt}Start`] || d.slot1Start || '';
const slotEnd   = d[`slot${opt}End`]   || d.slot1End   || '';
const slotId    = d[`slot${opt}Id`]    || d.slot1Id    || '';

return {
  json: {
    ...d,
    confirmedSlotStart: slotStart,
    confirmedSlotEnd:   slotEnd,
    confirmedSlotId:    slotId,
    calendarTitle:      `${d.appointmentType} — ${d.senderName}`,
    calendarDesc:       `Patient: ${d.senderName}\nEmail: ${d.senderEmail}\nType: ${d.appointmentType}\nBooked: ${new Date().toISOString()}`
  }
};

const d = $input.item.json;
const firstName = d.firstName || 'there';
let body = `Dear ${firstName},

Thank you so much for getting in touch with us.

// ▼▼▼ PASTE YOUR ADULT ADHD ASSESSMENT TEMPLATE HERE ▼▼▼

We would be delighted to support you through our adult ADHD assessment pathway. Our assessments are carried out by experienced specialist consultants in a thorough, compassionate evaluation tailored to you.

// ▲▲▲ END OF TEMPLATE ▲▲▲
`;
if (d.mentionsWaitingTime) body += `
Regarding waiting times: we are currently seeing new patients within approximately [X weeks]. We will confirm your exact date once your information is received.
`;
if (d.mentionsPrice) body += `
Regarding fees: our adult ADHD assessment is priced at [£XXX]. We will provide a full breakdown when confirming your appointment.
`;
if (d.location) body += `
We note you mentioned ${d.location} — we have options available that would be convenient for you.
`;
body += `
To take the next step, please reply to this email or call us on [PHONE NUMBER].

Warm regards,
Admin Team
REPLACE_WITH_CLINIC_NAME`;
return { json: { ...d, emailSubject: `Re: ${d.subject}`, emailBody: body, categoryLabel: 'Adult ADHD Assessment', ccEmail: 'REPLACE_ADULT_ADHD_CONSULTANT@yourclinic.co.uk' } };

